                const comps = hasRealComps ? realComps : (P.competitors||[]).filter(c=>!_isFakeComp(c)).slice(0,10);
                // Indicateurs RÉELS pour la page de couverture (basés sur le scan carte + données de fiche, pas de chiffres fabriqués)
