                const _productsSugg = (_ext.products?.suggested||[]).filter(s=>s&&!(typeof s==="string"?s:s.name||"").includes("[")).slice(0,3);
                const rm1=U.month1||{}; const rm2=U.month2||{}; const rm3=U.month3||{};
